"""Actual WDF transport source, explicit framework/reference/clock models."""
from pathlib import Path
import argparse,hashlib,json,subprocess
a=argparse.ArgumentParser();a.add_argument('--output',type=Path,required=True);args=a.parse_args();w=Path(__file__).resolve().parent.parent;o=args.output.resolve();o.mkdir(exist_ok=False)
code=(w/'tests/test-provider.c').read_text();body=(w/'source/provider_io.c').read_text().replace('#include <ntifs.h>','').replace('#include <wdf.h>','');code=code.replace('#include "provider_io.c"',body);(o/'model.c').write_text(code)
r=subprocess.run(['clang','-std=c11','-O1','-g','-Wall','-Wextra','-Werror','-Wno-multichar','-fsanitize=address,undefined','-I'+str(w/'source'),str(o/'model.c'),str(w/'source/health_capture.c'),'-o',str(o/'test')],capture_output=True,text=True);(o/'compiler.txt').write_text(r.stdout+r.stderr);assert not r.returncode,r.stderr
old=w.parent/'charging-G177/private';inputs=[old/'cycle-enabled-early-G167.bin',old/'cycle-enabled-early-G160.bin'];r=subprocess.run([str(o/'test'),*[str(f)for f in inputs],str(o/'io-success.bin')],capture_output=True,text=True);(o/'output.txt').write_text(r.stdout+r.stderr);assert not r.returncode,r.stdout+r.stderr
v=json.loads(r.stdout);sha=lambda f:hashlib.sha256(f.read_bytes()).hexdigest();v['source_sha256']={str(f.relative_to(w)):sha(f)for f in [w/'source/provider_io.c',w/'source/provider_io.h',w/'source/health_capture.c',w/'source/health_capture.h',w/'source/health_layout.h',w/'tests/test-provider.c',Path(__file__).resolve()]};v['input_sha256']={str(f):sha(f)for f in inputs};v['limits']=['Explicit WDF object/refcount/cancel/clock models; no native timeout or kernel target lifetime qualification.','Uses only existing G177 frozen values; no new physical read.'];(o/'tests.json').write_text(json.dumps(v,indent=2)+'\n');print({k:v[k]for k in ['passed','cases','delayed_timeout_buffers_checked','native_operations']})
